/**
 * Policy Clauses — Asset Management (p07-p09)
 * p07 = Asset Governance: ownership, classification, lifecycle, disposal, compliance
 * p08 = Technical Inventory & Dependency Mapping: data model, CMDB, dependency analysis, SPOF
 * Based on ISO 27001:2022, BSI IT-Grundschutz, NIST CSF 2.0, NIS2 Art.21
 */
import type { PolicyClause } from "../policyClauseTemplates";

// ═══════════════════════════════════════════════════
// P07 — Asset-Management-Richtlinie (Asset Governance)
// Focus: WHO owns it, HOW it's classified, lifecycle rules
// ═══════════════════════════════════════════════════
const p07: PolicyClause[] = [
  { id: "p07-c00", title: "Zweck und Geltungsbereich der Asset-Management-Richtlinie", titleEn: "Purpose & Scope of Asset Management Policy", description: "Diese Richtlinie definiert die Grundsätze für die Verwaltung und den Schutz aller Informationswerte der Organisation — Hardware, Software, Daten, Cloud-Ressourcen, OT/ICS-Systeme und physische Medien. Sie legt die organisatorischen Verantwortlichkeiten, Klassifizierungsstandards und Lebenszyklus-Anforderungen fest, die für jeden Informationswert gelten.", descriptionEn: "This policy defines the principles for managing and protecting all information assets of the organisation — hardware, software, data, cloud resources, OT/ICS systems, and physical media. It establishes organisational responsibilities, classification standards, and lifecycle requirements applicable to every information asset.", reason: "Ohne eine übergreifende Asset-Management-Richtlinie fehlt der einheitliche Rahmen für die Verwaltung aller Informationswerte.", reasonEn: "Without an overarching asset management policy, the unified framework for managing all information assets is missing.", whenRequired: "Immer erforderlich als Grundlage des Asset Managements.", whenRequiredEn: "Always required as the foundation of asset management.", sources: ["ISO 27001:2022 A.5.9", "NIS2 Art.21(2)(a)", "BSI IT-Grundschutz ORP.1", "NIST CSF 2.0 ID.AM"] },
  { id: "p07-c01", title: "Asset-Eigentümerschaft und Verantwortlichkeiten", titleEn: "Asset Ownership & Responsibilities", description: "Jedem Asset muss ein verantwortlicher Eigentümer zugewiesen werden, der für Schutz, Klassifizierung, Zugriffssteuerung und Lebenszyklusentscheidungen verantwortlich ist. Der Eigentümer muss die Befugnis haben, Schutzmaßnahmen festzulegen und Zugriffsberechtigungen zu genehmigen. Eigentümerwechsel müssen innerhalb von fünf Werktagen dokumentiert und im Inventar aktualisiert werden.", descriptionEn: "Each asset must be assigned a responsible owner accountable for protection, classification, access control, and lifecycle decisions. The owner must have authority to determine protection measures and approve access permissions. Ownership changes must be documented and updated in the inventory within five business days.", reason: "Ohne klare Eigentümerschaft fehlt die Verantwortlichkeit — niemand fühlt sich zuständig und Schutzmaßnahmen werden vernachlässigt.", reasonEn: "Without clear ownership, accountability is missing — nobody feels responsible and protection measures are neglected.", whenRequired: "Immer erforderlich für jedes inventarisierte Asset.", whenRequiredEn: "Always required for every inventoried asset.", sources: ["ISO 27001:2022 A.5.9", "BSI IT-Grundschutz ORP.1.A1", "NIST CSF 2.0 ID.AM-02"] },
  { id: "p07-c02", title: "Asset-Klassifizierung nach Schutzbedarf", titleEn: "Asset Classification by Protection Needs", description: "Assets müssen nach Vertraulichkeit, Integrität und Verfügbarkeit klassifiziert werden. Mindestens vier Schutzstufen müssen definiert werden (z.B. Öffentlich, Intern, Vertraulich, Streng Vertraulich). Die Klassifizierung bestimmt die erforderlichen technischen und organisatorischen Schutzmaßnahmen und muss bei wesentlichen Änderungen überprüft werden.", descriptionEn: "Assets must be classified by confidentiality, integrity, and availability. At least four protection levels must be defined (e.g., Public, Internal, Confidential, Strictly Confidential). Classification determines required technical and organisational protection measures and must be reviewed upon significant changes.", reason: "Ohne Klassifizierung werden alle Assets gleich behandelt — kritische untergeschützt, unkritische übergeschützt, Ressourcen ineffizient eingesetzt.", reasonEn: "Without classification, all assets are treated equally — critical ones under-protected, non-critical over-protected, resources inefficiently allocated.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.12-5.13", "BSI IT-Grundschutz CON.1", "NIST CSF 2.0 ID.AM-05"] },
  { id: "p07-c03", title: "Asset-Lebenszyklusmanagement", titleEn: "Asset Lifecycle Management", description: "Wir müssen den gesamten Lebenszyklus jedes Assets verwalten — Beschaffung und Genehmigung, Inbetriebnahme und Konfiguration, Betrieb und Wartung, Außerbetriebnahme und sichere Entsorgung. Jede Phase muss mit definierten Sicherheitsanforderungen und Genehmigungsschritten dokumentiert werden. Übergänge zwischen Phasen müssen nachvollziehbar protokolliert werden.", descriptionEn: "We must manage the complete lifecycle of each asset — procurement and approval, commissioning and configuration, operation and maintenance, decommissioning and secure disposal. Each phase must be documented with defined security requirements and approval steps. Transitions between phases must be traceably logged.", reason: "Assets ohne Lebenszyklusmanagement werden vergessen, veralten und werden zu unkontrollierten Sicherheitsrisiken.", reasonEn: "Assets without lifecycle management are forgotten, become outdated, and turn into uncontrolled security risks.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.9-5.11", "BSI IT-Grundschutz ORP.1", "NIST CSF 2.0 ID.AM"] },
  { id: "p07-c04", title: "Sichere Asset-Entsorgung und Datenlöschung", titleEn: "Secure Asset Disposal & Data Erasure", description: "Assets müssen bei Außerbetriebnahme sicher entsorgt werden. Datenträger müssen nach anerkannten Standards gelöscht (NIST SP 800-88) oder physisch vernichtet (DIN 66399) werden. Für jede Entsorgung muss ein Nachweis erstellt werden, der Asset-Kennung, Löschmethode, Datum und verantwortliche Person dokumentiert. Drittanbieter-Entsorgung erfordert vertragliche Sicherheitsgarantien.", descriptionEn: "Assets must be securely disposed of when decommissioned. Storage media must be erased per recognised standards (NIST SP 800-88) or physically destroyed (DIN 66399). For each disposal, evidence must be created documenting asset ID, erasure method, date, and responsible person. Third-party disposal requires contractual security guarantees.", reason: "Unsichere Entsorgung kann zu Datenlecks und schwerwiegenden Compliance-Verstößen führen.", reasonEn: "Insecure disposal can lead to data leaks and severe compliance violations.", whenRequired: "Bei jeder Asset-Außerbetriebnahme.", whenRequiredEn: "For every asset decommissioning.", sources: ["ISO 27001:2022 A.7.14", "BSI IT-Grundschutz CON.6", "NIST SP 800-88"] },
  { id: "p07-c05", title: "Cloud-Asset-Governance", titleEn: "Cloud Asset Governance", description: "Cloud-Ressourcen (IaaS, PaaS, SaaS) müssen denselben Governance-Anforderungen wie On-Premises-Assets unterliegen. Die geteilte Verantwortung (Shared Responsibility Model) muss pro Cloud-Dienst dokumentiert sein — welche Schutzmaßnahmen der Anbieter verantwortet und welche die Organisation selbst sicherstellen muss. Cloud-Verträge müssen Sicherheitsanforderungen, Audit-Rechte und Exit-Strategien enthalten.", descriptionEn: "Cloud resources (IaaS, PaaS, SaaS) must be subject to the same governance requirements as on-premises assets. Shared responsibility must be documented per cloud service — which protections the provider manages and which we must ensure. Cloud contracts must include security requirements, audit rights, and exit strategies.", reason: "Cloud-Assets unterliegen häufig keiner klaren Governance und entziehen sich so der Sicherheitskontrolle.", reasonEn: "Cloud assets frequently lack clear governance, thus evading security controls.", whenRequired: "Erforderlich für alle Organisationen mit Cloud-Nutzung.", whenRequiredEn: "Required for all organisations using cloud services.", sources: ["ISO 27001:2022 A.5.23", "BSI C5:2020", "NIST CSF 2.0 ID.AM-02"] },
  { id: "p07-c06", title: "Software-Asset-Management (SAM)", titleEn: "Software Asset Management (SAM)", description: "Wir müssen ein Software-Asset-Management betreiben — genehmigte Softwareliste (Whitelist), Lizenzverwaltung und -compliance, Versions-Tracking und End-of-Support-Überwachung. Nicht autorisierte Software muss erkannt und entfernt werden. Lizenz-Audits müssen mindestens jährlich durchgeführt werden.", descriptionEn: "We must operate software asset management — approved software list (whitelist), licence management and compliance, version tracking, and end-of-support monitoring. Unauthorised software must be detected and removed. Licence audits must be conducted at least annually.", reason: "Nicht verwaltete Software ist eine der häufigsten Ursachen für Schwachstellen und Lizenzverstöße.", reasonEn: "Unmanaged software is one of the most common causes of vulnerabilities and licence violations.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.9", "BSI IT-Grundschutz APP.6", "NIST CSF 2.0 ID.AM-02"] },
  { id: "p07-c07", title: "OT/ICS-Asset-Governance", titleEn: "OT/ICS Asset Governance", description: "Operative Technologie (OT) und industrielle Steuerungssysteme (ICS) müssen gesonderten Governance-Regeln unterliegen, die ihre längeren Lebenszyklen, eingeschränkten Patch-Möglichkeiten und Verfügbarkeitsanforderungen berücksichtigen. Die Verantwortlichkeiten zwischen IT- und OT-Teams müssen klar abgegrenzt und dokumentiert werden.", descriptionEn: "Operational Technology (OT) and Industrial Control Systems (ICS) must be subject to separate governance rules accounting for their longer lifecycles, limited patching options, and availability requirements. Responsibilities between IT and OT teams must be clearly delineated and documented.", reason: "OT-Systeme haben andere Lebenszyklen und Risikoprofile als IT — eine gemeinsame Governance-Behandlung ist unzureichend.", reasonEn: "OT systems have different lifecycles and risk profiles than IT — joint governance treatment is insufficient.", whenRequired: "Erforderlich für Organisationen mit OT/ICS-Systemen.", whenRequiredEn: "Required for organisations with OT/ICS systems.", sources: ["IEC 62443", "NIS2 Art.21(2)(a)", "BSI ICS-Security Kompendium"] },
  { id: "p07-c08", title: "Asset-Bewertung und Schutzpriorisierung", titleEn: "Asset Valuation & Protection Prioritisation", description: "Wir müssen den Wert jedes Assets bestimmen — geschäftliche Bedeutung, Wiederbeschaffungskosten, Auswirkung bei Kompromittierung oder Verlust. Die Bewertung muss als Grundlage für die risikobasierte Priorisierung von Schutzmaßnahmen dienen und mit dem zentralen Risikomanagement-Prozess verknüpft sein.", descriptionEn: "We must determine each asset's value — business importance, replacement cost, impact of compromise or loss. Valuation must serve as the basis for risk-based prioritisation of protection measures and be linked with the central risk management process.", reason: "Ohne Bewertung werden Ressourcen gleichmäßig statt risikobasiert verteilt und kritische Assets möglicherweise unzureichend geschützt.", reasonEn: "Without valuation, resources are distributed evenly instead of risk-based, potentially leaving critical assets insufficiently protected.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.9", "BSI-Standard 200-3", "NIST CSF 2.0 ID.AM-05"] },
  { id: "p07-c09", title: "Asset-Kennzeichnung und Labelling", titleEn: "Asset Labelling & Marking", description: "Physische Assets müssen eindeutig gekennzeichnet werden (Inventaraufkleber, Barcode/QR-Code). Digitale Assets müssen eindeutige Identifikatoren haben. Die Kennzeichnung muss den Eigentümer und die Schutzklassifizierung erkennen lassen. Die Kennzeichnungsstandards müssen organisationsweit einheitlich sein.", descriptionEn: "Physical assets must be uniquely labelled (inventory stickers, barcode/QR code). Digital assets must have unique identifiers. Labelling must indicate owner and protection classification. Labelling standards must be uniform across the organisation.", reason: "Ohne Kennzeichnung können Assets nicht zuverlässig identifiziert und ihrem Eigentümer zugeordnet werden.", reasonEn: "Without labelling, assets cannot be reliably identified and assigned to their owner.", whenRequired: "Immer erforderlich für physische Assets.", whenRequiredEn: "Always required for physical assets.", sources: ["ISO 27001:2022 A.5.13", "BSI IT-Grundschutz INF.1", "NIST CSF 2.0 ID.AM-01"] },
  { id: "p07-c10", title: "Asset-Transfer und sichere Weitergabe", titleEn: "Asset Transfer & Secure Handover", description: "Der Transfer und Transport von Assets (physisch und digital) muss gesichert erfolgen. Für physische Transporte müssen Übergabeprotokolle mit Absender, Empfänger, Datum und Zustandsbewertung geführt werden. Digitale Transfers müssen verschlüsselt erfolgen und nachvollziehbar protokolliert werden.", descriptionEn: "Asset transfer and transport (physical and digital) must be secured. For physical transfers, handover protocols with sender, receiver, date, and condition assessment must be maintained. Digital transfers must be encrypted and traceably logged.", reason: "Ungesicherter Transfer kann zu Verlust, Diebstahl oder Manipulation von Assets führen.", reasonEn: "Unsecured transfer can lead to loss, theft, or manipulation of assets.", whenRequired: "Bei jedem Asset-Transfer.", whenRequiredEn: "For every asset transfer.", sources: ["ISO 27001:2022 A.7.10", "BSI IT-Grundschutz SYS.3.4", "NIST CSF 2.0 PR.DS"] },
  { id: "p07-c11", title: "Bring Your Own Device (BYOD)", titleEn: "Bring Your Own Device (BYOD)", description: "Wenn die Organisation BYOD erlaubt, müssen klare Regeln definiert werden — Mindestanforderungen an Gerätesicherheit (OS-Version, Verschlüsselung, PIN), Trennung privater und dienstlicher Daten (Containerisierung), Remote-Wipe-Möglichkeit bei Verlust, Datenschutzbestimmungen und Haftungsregelungen.", descriptionEn: "If we allow BYOD, clear rules must be defined — minimum device security requirements (OS version, encryption, PIN), separation of private and business data (containerisation), remote wipe capability upon loss, data protection provisions, and liability regulations.", reason: "BYOD-Geräte erweitern die Angriffsfläche erheblich, wenn sie nicht angemessen verwaltet werden.", reasonEn: "BYOD devices significantly expand the attack surface if not appropriately managed.", whenRequired: "Erforderlich wenn BYOD erlaubt ist.", whenRequiredEn: "Required when BYOD is permitted.", sources: ["ISO 27001:2022 A.8.1", "BSI IT-Grundschutz SYS.3.2.2", "NIST CSF 2.0 PR.AA"] },
  { id: "p07-c12", title: "Drittanbieter-Asset-Verantwortung", titleEn: "Third-Party Asset Responsibility", description: "Für Assets, die von Drittanbietern verwaltet oder gehostet werden, muss die Verantwortungsabgrenzung gemäß Shared-Responsibility-Modell vertraglich und organisatorisch dokumentiert werden. Wir müssen sicherstellen, dass für jedes Drittanbieter-Asset ein interner Ansprechpartner als Eigentümer benannt ist.", descriptionEn: "For assets managed or hosted by third parties, responsibility delineation per shared responsibility model must be contractually and organisationally documented. We must ensure an internal contact is designated as owner for every third-party asset.", reason: "Ohne klare Verantwortungsabgrenzung bei Drittanbieter-Assets entstehen Schutzlücken, weil beide Seiten annehmen, die andere sei zuständig.", reasonEn: "Without clear responsibility delineation for third-party assets, protection gaps arise because both sides assume the other is responsible.", whenRequired: "Erforderlich bei Nutzung von Managed Services und Cloud.", whenRequiredEn: "Required when using managed services and cloud.", sources: ["ISO 27001:2022 A.5.19-5.22", "NIS2 Art.21(2)(d)", "BSI C5:2020"] },
  { id: "p07-c13", title: "End-of-Life- und End-of-Support-Governance", titleEn: "End-of-Life & End-of-Support Governance", description: "Wir müssen End-of-Life (EOL) und End-of-Support (EOS) Daten aller Assets zentral überwachen. Für Assets ohne Herstellersupport müssen spätestens 6 Monate vor EOS Migrationsplanung, kompensierende Kontrollen oder Ablösung eingeleitet werden. Der Betrieb von EOL-Assets bedarf einer formalen Risikoakzeptanz durch den Asset-Eigentümer.", descriptionEn: "We must centrally monitor end-of-life (EOL) and end-of-support (EOS) dates of all assets. For assets losing vendor support, migration planning, compensating controls, or replacement must be initiated at least 6 months before EOS. Operating EOL assets requires formal risk acceptance by the asset owner.", reason: "EOL-Systeme erhalten keine Sicherheitsupdates und sind besonders verwundbar — sie erfordern bewusste Risikoentscheidungen.", reasonEn: "EOL systems receive no security updates and are particularly vulnerable — they require conscious risk decisions.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "BSI IT-Grundschutz SYS.1.1.A42", "NIST CSF 2.0 PR.IP"] },
  { id: "p07-c14", title: "Asset-Compliance und regulatorische Zuordnung", titleEn: "Asset Compliance & Regulatory Mapping", description: "Assets müssen den regulatorischen Anforderungen zugeordnet werden — Datenlokalisierung für DSGVO, Sicherheitszertifizierungen für KRITIS, Exportkontrollvorschriften, branchenspezifische Regulierung. Compliance-Status muss pro Asset dokumentiert und bei Audit-Anforderungen nachweisbar sein.", descriptionEn: "Assets must be mapped to regulatory requirements — data localisation for GDPR, security certifications for critical infrastructure, export control regulations, sector-specific regulation. Compliance status must be documented per asset and demonstrable for audit requirements.", reason: "Nicht-konforme Assets können regulatorische Sanktionen und Bußgelder nach sich ziehen.", reasonEn: "Non-compliant assets can result in regulatory sanctions and fines.", whenRequired: "Erforderlich für alle regulierten Organisationen.", whenRequiredEn: "Required for all regulated organisations.", sources: ["ISO 27001:2022 A.5.31", "NIS2 Art.21", "DSGVO Art.32"] },
  { id: "p07-c15", title: "Notfall-Asset-Liste und Wiederherstellungspriorisierung", titleEn: "Emergency Asset List & Recovery Prioritisation", description: "Wir müssen eine priorisierte Liste kritischer Assets für Notfallsituationen pflegen — Systeme, die für die Wiederherstellung kritischer Geschäftsprozesse unverzichtbar sind. Diese Liste muss offline verfügbar sein (gedruckt oder auf separatem Medium gespeichert) und quartalsweise aktualisiert werden.", descriptionEn: "We must maintain a prioritised list of critical assets for emergency situations — systems essential for restoring critical business processes. This list must be available offline (printed or stored on separate medium) and updated quarterly.", reason: "Im Notfall muss sofort klar sein, welche Assets priorisiert wiederhergestellt werden müssen — ohne IT-Systemzugriff.", reasonEn: "In emergencies, it must be immediately clear which assets must be prioritised for restoration — without IT system access.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.29-5.30", "BSI-Standard 200-4", "NIST CSF 2.0 RC.RP"] },
  { id: "p07-c16", title: "Asset-Management-Reporting", titleEn: "Asset Management Reporting", description: "Wir müssen regelmäßig Berichte zum Asset-Bestand erstellen — Gesamtzahl nach Kategorie, Klassifizierungsverteilung, Altersverteilung, EOL-Status, Eigentümer-Abdeckung und offene Governance-Maßnahmen. Ein Management-Dashboard mit KPIs wird empfohlen.", descriptionEn: "We must regularly create reports on asset inventory — total count by category, classification distribution, age distribution, EOL status, owner coverage, and open governance actions. A management dashboard with KPIs is recommended.", reason: "Ohne Reporting fehlt der Überblick über die Asset-Landschaft und deren Governance-Status.", reasonEn: "Without reporting, overview of the asset landscape and its governance status is missing.", whenRequired: "Empfohlen mindestens vierteljährlich.", whenRequiredEn: "Recommended at least quarterly.", sources: ["ISO 27001:2022 §9.1", "BSI IT-Grundschutz ORP.1", "NIST CSF 2.0 ID.AM"] },
  { id: "p07-c17", title: "Asset-Beschaffungssicherheit", titleEn: "Asset Procurement Security", description: "Vor der Beschaffung neuer Assets müssen Sicherheitsanforderungen definiert und als Auswahlkriterium berücksichtigt werden — Herstellersicherheit, Update-Verfügbarkeit, Zertifizierungen, Kompatibilität mit bestehenden Schutzmaßnahmen. Beschaffungsentscheidungen müssen die Sicherheitsbewertung dokumentieren.", descriptionEn: "Before procuring new assets, security requirements must be defined and considered as selection criteria — vendor security, update availability, certifications, compatibility with existing protection measures. Procurement decisions must document the security assessment.", reason: "Ohne Sicherheitsanforderungen bei der Beschaffung werden unsichere Produkte eingeführt, die nachträglich schwer zu schützen sind.", reasonEn: "Without security requirements during procurement, insecure products are introduced that are difficult to protect retroactively.", whenRequired: "Bei jeder wesentlichen Asset-Beschaffung.", whenRequiredEn: "For every significant asset procurement.", sources: ["ISO 27001:2022 A.5.9, A.8.25", "BSI IT-Grundschutz ORP.4", "NIST CSF 2.0 GV.SC"] },
  { id: "p07-c18", title: "Informationsmedien-Handhabung", titleEn: "Information Media Handling", description: "Wechseldatenträger (USB, externe Festplatten) und physische Dokumente müssen gemäß ihrer Klassifizierung gehandhabt werden. Vertrauliche Medien müssen verschlüsselt, sicher aufbewahrt und bei Nichtgebrauch gesperrt werden. Die Nutzung nicht genehmigter Wechseldatenträger muss technisch unterbunden werden.", descriptionEn: "Removable media (USB, external drives) and physical documents must be handled according to their classification. Confidential media must be encrypted, securely stored, and locked when not in use. Use of unapproved removable media must be technically prevented.", reason: "Wechseldatenträger sind ein häufiger Vektor für Datenverlust und Malware-Einschleusung.", reasonEn: "Removable media are a common vector for data loss and malware introduction.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.10-7.14", "BSI IT-Grundschutz SYS.3.4", "NIST CSF 2.0 PR.DS"] },
  { id: "p07-c19", title: "Überprüfung der Asset-Management-Richtlinie", titleEn: "Review of Asset Management Policy", description: "Diese Richtlinie muss mindestens jährlich oder bei wesentlichen Veränderungen (neue Technologien, Reorganisation, regulatorische Änderungen) überprüft und aktualisiert werden. Erkenntnisse aus Audits, Vorfällen und Asset-Management-Berichten müssen in die Überprüfung einfließen.", descriptionEn: "This policy must be reviewed and updated at least annually or upon significant changes (new technologies, reorganisation, regulatory changes). Insights from audits, incidents, and asset management reports must feed into the review.", reason: "Eine veraltete Richtlinie bildet die aktuelle Asset-Landschaft nicht mehr korrekt ab und führt zu Schutzlücken.", reasonEn: "An outdated policy no longer correctly reflects the current asset landscape and leads to protection gaps.", whenRequired: "Mindestens jährlich.", whenRequiredEn: "At least annually.", sources: ["ISO 27001:2022 A.5.1", "BSI-Standard 200-1", "NIST CSF 2.0 GV.PO"] },
];

// ═══════════════════════════════════════════════════
// P08 — IT-Asset-Inventar & Abhängigkeits-Richtlinie (Technical Inventory & Dependency Mapping)
// Focus: WHERE assets are, HOW they connect, WHAT depends on what
// ═══════════════════════════════════════════════════
const p08: PolicyClause[] = [
  { id: "p08-c00", title: "Inventarisierungsstandard und Datenmodell", titleEn: "Inventory Standard & Data Model", description: "Wir müssen einen einheitlichen Inventarisierungsstandard definieren, der für jedes Asset mindestens folgende Attribute erfasst: Bezeichnung, Typ, Standort, Netzwerksegment, IP-Adresse/FQDN, Betriebssystem, Softwareversion, Patch-Stand, zugehöriger Dienst und Abhängigkeiten. Das Datenmodell muss erweiterbar und mit gängigen CMDB-Standards kompatibel sein.", descriptionEn: "We must define a uniform inventory standard capturing at minimum for each asset: name, type, location, network segment, IP address/FQDN, operating system, software version, patch level, associated service, and dependencies. The data model must be extensible and compatible with common CMDB standards.", reason: "Ohne standardisiertes Datenmodell ist das Inventar unvollständig, inkonsistent und nicht automatisierbar.", reasonEn: "Without a standardised data model, inventory is incomplete, inconsistent, and cannot be automated.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.9", "BSI IT-Grundschutz ORP.1", "NIST CSF 2.0 ID.AM-01"] },
  { id: "p08-c01", title: "CMDB und Konfigurationsmanagement", titleEn: "CMDB & Configuration Management", description: "Wir müssen eine Configuration Management Database (CMDB) oder ein gleichwertiges System betreiben, das den aktuellen Konfigurationsstand aller Assets dokumentiert — installierte Software, offene Ports, aktive Dienste, Netzwerkverbindungen. Jede Konfigurationsänderung muss dem Change-Management-Prozess folgen und in der CMDB nachvollziehbar protokolliert werden.", descriptionEn: "We must operate a Configuration Management Database (CMDB) or equivalent system documenting the current configuration state of all assets — installed software, open ports, active services, network connections. Every configuration change must follow the change management process and be traceably logged in the CMDB.", reason: "Ohne CMDB sind Konfigurationsänderungen nicht nachvollziehbar und Fehlkonfigurationen als Sicherheitslücke nicht erkennbar.", reasonEn: "Without CMDB, configuration changes are not traceable and misconfigurations as security gaps are not detectable.", whenRequired: "Empfohlen für Organisationen mit >50 IT-Systemen.", whenRequiredEn: "Recommended for organisations with >50 IT systems.", sources: ["ISO 27001:2022 A.8.9", "BSI IT-Grundschutz OPS.1.1.3", "NIST CSF 2.0 ID.AM"] },
  { id: "p08-c02", title: "Automatisierte Asset-Erkennung und Inventar-Synchronisation", titleEn: "Automated Asset Discovery & Inventory Synchronisation", description: "Wir müssen automatisierte Tools zur Asset-Erkennung einsetzen — Network Scanning, Agent-basierte Erfassung, Cloud-API-Integration, DHCP/DNS-Korrelation. Automatisierte Ergebnisse müssen kontinuierlich mit dem Inventar synchronisiert werden. Nicht autorisierte Geräte (Rogue Devices) müssen automatisch erkannt und alarmiert werden.", descriptionEn: "We must use automated asset discovery tools — network scanning, agent-based collection, cloud API integration, DHCP/DNS correlation. Automated results must be continuously synchronised with inventory. Unauthorised devices (rogue devices) must be automatically detected and alerted.", reason: "Manuelle Inventarisierung ist fehleranfällig und veraltet innerhalb von Tagen in dynamischen Umgebungen.", reasonEn: "Manual inventorying is error-prone and becomes outdated within days in dynamic environments.", whenRequired: "Empfohlen für Organisationen mit >100 Assets.", whenRequiredEn: "Recommended for organisations with >100 assets.", sources: ["NIST CSF 2.0 ID.AM-01", "ISO 27001:2022 A.5.9", "BSI IT-Grundschutz OPS.1.1.5"] },
  { id: "p08-c03", title: "Abhängigkeitsmapping und Visualisierung", titleEn: "Dependency Mapping & Visualisation", description: "Abhängigkeiten zwischen Assets müssen systematisch erfasst und visualisiert werden — Netzwerkverbindungen, Datenflüsse, Serviceabhängigkeiten, Vertrauensgrenzen. Grafische Topologie-Diagramme müssen erstellt, aktuell gehalten und für Incident-Response und Change-Management nutzbar sein.", descriptionEn: "Dependencies between assets must be systematically captured and visualised — network connections, data flows, service dependencies, trust boundaries. Graphical topology diagrams must be created, kept current, and usable for incident response and change management.", reason: "Unbekannte Abhängigkeiten führen zu kaskadierenden Ausfällen und unvollständigen Risikoanalysen.", reasonEn: "Unknown dependencies lead to cascading failures and incomplete risk analyses.", whenRequired: "Immer erforderlich für kritische Dienste.", whenRequiredEn: "Always required for critical services.", sources: ["ISO 27001:2022 A.5.9", "NIS2 Art.21(2)(a)", "BSI-Standard 200-3 Kap.4.5"] },
  { id: "p08-c04", title: "Datenflussanalyse und -dokumentation", titleEn: "Data Flow Analysis & Documentation", description: "Wir müssen Datenflüsse zwischen Assets, Systemen und externen Schnittstellen dokumentieren. Für jeden Datenfluss müssen Art der Daten, Schutzbedarf, Verschlüsselungsstatus, Protokoll und beteiligte Parteien erfasst werden. Datenflüsse mit personenbezogenen Daten müssen separat gekennzeichnet werden.", descriptionEn: "We must document data flows between assets, systems, and external interfaces. For each data flow, data type, protection needs, encryption status, protocol, and involved parties must be captured. Data flows with personal data must be separately marked.", reason: "Ohne Datenflussanalyse sind Datenschutz- und Sicherheitsrisiken nicht vollständig erkennbar.", reasonEn: "Without data flow analysis, data protection and security risks are not fully identifiable.", whenRequired: "Erforderlich für DSGVO-Compliance und NIS2.", whenRequiredEn: "Required for GDPR compliance and NIS2.", sources: ["DSGVO Art.30", "ISO 27001:2022 A.5.14", "BSI IT-Grundschutz NET.1.1"] },
  { id: "p08-c05", title: "Kritikalitätsvererbung über Abhängigkeitsketten", titleEn: "Criticality Inheritance Across Dependency Chains", description: "Assets, die kritische Dienste unterstützen, müssen die Kritikalität des jeweiligen Dienstes erben. Wenn ein Asset von einem kritischen Dienst abhängt, muss es mindestens die gleiche Schutzstufe erhalten. Die Vererbung muss über mehrere Ebenen der Abhängigkeitskette kaskadieren.", descriptionEn: "Assets supporting critical services must inherit the criticality of the respective service. When an asset is depended upon by a critical service, it must receive at least the same protection level. Inheritance must cascade across multiple levels of the dependency chain.", reason: "Ohne Kritikalitätsvererbung werden unterstützende Assets untergeschützt und schaffen Schwachpunkte in der Kette.", reasonEn: "Without criticality inheritance, supporting assets are under-protected, creating weak points in the chain.", whenRequired: "Immer erforderlich für dienst-abhängige Assets.", whenRequiredEn: "Always required for service-dependent assets.", sources: ["ISO 27001:2022 A.5.9", "BSI-Standard 200-3", "NIST CSF 2.0 ID.AM-05"] },
  { id: "p08-c06", title: "Single Points of Failure (SPOF) Identifikation", titleEn: "Single Points of Failure (SPOF) Identification", description: "Wir müssen Single Points of Failure in unseren Abhängigkeitsketten systematisch identifizieren und dokumentieren. Für jeden SPOF müssen Redundanzmaßnahmen, Failover-Konfigurationen oder formale Risikoacceptanz-Entscheidungen mit Begründung dokumentiert werden.", descriptionEn: "We must systematically identify and document Single Points of Failure in dependency chains. For each SPOF, redundancy measures, failover configurations, or formal risk acceptance decisions with rationale must be documented.", reason: "SPOFs sind die häufigste Ursache für Totalausfälle kritischer Dienste.", reasonEn: "SPOFs are the most common cause of total outages of critical services.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.14", "BSI-Standard 200-4", "NIST CSF 2.0 PR.IR"] },
  { id: "p08-c07", title: "Externes Schnittstelleninventar", titleEn: "External Interface Inventory", description: "Alle externen Schnittstellen (APIs, VPN-Tunnel, Datenaustausch mit Partnern, Cloud-Integrationen, B2B-Verbindungen) müssen inventarisiert werden, einschließlich Protokoll, Authentifizierungsmethode, Datenklassifizierung, Verfügbarkeitsanforderung und verantwortlichem Ansprechpartner.", descriptionEn: "All external interfaces (APIs, VPN tunnels, data exchange with partners, cloud integrations, B2B connections) must be inventoried, including protocol, authentication method, data classification, availability requirement, and responsible contact.", reason: "Externe Schnittstellen sind bevorzugte Angriffsvektoren und erfordern besondere Sichtbarkeit und Kontrolle.", reasonEn: "External interfaces are preferred attack vectors and require special visibility and control.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.20", "NIS2 Art.21(2)(b)", "BSI IT-Grundschutz NET.1.1"] },
  { id: "p08-c08", title: "Impact-Analyse bei Asset-Ausfall", titleEn: "Impact Analysis for Asset Failure", description: "Für jedes kritische Asset muss eine Impact-Analyse durchgeführt werden, die die Auswirkungen eines Ausfalls auf abhängige Dienste und Geschäftsprozesse quantifiziert. Die Analyse muss RTO/RPO-Werte, betroffene Nutzerzahlen und finanzielle Auswirkungen berücksichtigen.", descriptionEn: "For each critical asset, an impact analysis must be conducted quantifying the effects of failure on dependent services and business processes. The analysis must consider RTO/RPO values, affected user numbers, and financial impacts.", reason: "Ohne Impact-Analyse können Wiederherstellungsprioritäten nicht korrekt gesetzt werden.", reasonEn: "Without impact analysis, recovery priorities cannot be correctly set.", whenRequired: "Erforderlich für alle kritischen Assets.", whenRequiredEn: "Required for all critical assets.", sources: ["ISO 27001:2022 A.5.29", "BSI-Standard 200-4", "NIST CSF 2.0 ID.RA"] },
  { id: "p08-c09", title: "Automatisierte Abhängigkeitserkennung", titleEn: "Automated Dependency Discovery", description: "Wir sollten automatisierte Tools zur Erkennung von Abhängigkeiten einsetzen — Application Dependency Mapping (ADM), Traffic-Analyse, Service-Mesh-Monitoring, Container-Orchestrierung-APIs. Manuelle Erfassung muss automatisierte Ergebnisse bei Lücken ergänzen.", descriptionEn: "We should use automated tools for dependency discovery — Application Dependency Mapping (ADM), traffic analysis, service mesh monitoring, container orchestration APIs. Manual capture must supplement automated results where gaps exist.", reason: "Manuelle Abhängigkeitserfassung ist unvollständig und veraltet schnell, insbesondere in Cloud-nativen und Microservice-Architekturen.", reasonEn: "Manual dependency capture is incomplete and quickly outdated, especially in cloud-native and microservice architectures.", whenRequired: "Empfohlen ab 50 Assets.", whenRequiredEn: "Recommended from 50 assets.", sources: ["NIST CSF 2.0 ID.AM", "ISO 27001:2022 A.5.9", "BSI IT-Grundschutz OPS.1.1.5"] },
  { id: "p08-c10", title: "Lieferketten-Abhängigkeitsanalyse", titleEn: "Supply Chain Dependency Analysis", description: "Wir müssen im Abhängigkeitsregister erfassen, welche Assets von welchen externen Lieferanten und deren Produkten abhängen. Konzentrationsrisiken müssen quantifiziert werden — Anzahl der Assets pro Anbieter, Anteil der kritischen Assets je Lieferant, geographische Verteilung der Lieferkette. Die Analyse muss Single-Vendor-Abhängigkeiten und Kaskadeneffekte bei Lieferantenausfall auf Asset-Ebene sichtbar machen.", descriptionEn: "We must record in the dependency register which assets depend on which external suppliers and their products. Concentration risks must be quantified — number of assets per supplier, proportion of critical assets per supplier, geographical distribution of supply chain. The analysis must reveal single-vendor dependencies and cascade effects of supplier failure at asset level.", reason: "Ohne asset-bezogene Lieferkettenanalyse bleiben Konzentrationsrisiken und Kaskadeneffekte unsichtbar.", reasonEn: "Without asset-level supply chain analysis, concentration risks and cascade effects remain invisible.", whenRequired: "Erforderlich nach NIS2 Art.21(2)(d).", whenRequiredEn: "Required per NIS2 Art.21(2)(d).", sources: ["NIS2 Art.21(2)(d)", "ISO 27001:2022 A.5.21", "BSI IT-Grundschutz OPS.2.1"] },
  { id: "p08-c11", title: "Zentrales Abhängigkeitsregister", titleEn: "Central Dependency Register", description: "Wir müssen ein zentrales Abhängigkeitsregister führen, das alle identifizierten Abhängigkeiten mit Typ (technisch, organisatorisch, vertraglich), Kritikalität, Richtung (upstream/downstream), Status und letztem Überprüfungsdatum dokumentiert. Das Register muss mindestens halbjährlich überprüft werden.", descriptionEn: "We must maintain a central dependency register documenting all identified dependencies with type (technical, organisational, contractual), criticality, direction (upstream/downstream), status, and last review date. The register must be reviewed at least semi-annually.", reason: "Ohne zentrales Register sind Abhängigkeiten über verschiedene Teams verstreut und nicht aggregiert sichtbar.", reasonEn: "Without a central register, dependencies are scattered across teams and not visibly aggregated.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.9", "BSI-Standard 200-3", "NIST CSF 2.0 ID.AM"] },
  { id: "p08-c12", title: "Änderungsauswirkungsanalyse (Change Impact)", titleEn: "Change Impact Analysis", description: "Vor jeder wesentlichen Änderung an einem Asset muss eine Auswirkungsanalyse auf abhängige Systeme und Dienste durchgeführt werden. Die Analyse muss die Abhängigkeitskette berücksichtigen und Teil des Change-Management-Prozesses sein. Ergebnisse müssen dokumentiert und freigegeben werden.", descriptionEn: "Before any significant change to an asset, an impact analysis on dependent systems and services must be conducted. The analysis must consider the dependency chain and be part of the change management process. Results must be documented and approved.", reason: "Änderungen ohne Auswirkungsanalyse können kaskadierende Störungen in der gesamten Abhängigkeitskette verursachen.", reasonEn: "Changes without impact analysis can cause cascading disruptions across the entire dependency chain.", whenRequired: "Bei jeder wesentlichen Änderung.", whenRequiredEn: "For every significant change.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3", "NIST CSF 2.0 PR.IP"] },
  { id: "p08-c13", title: "Geographische Verteilung und Standortrisiken", titleEn: "Geographic Distribution & Location Risks", description: "Wir müssen die geographische Verteilung unserer Assets dokumentieren — Rechenzentren, Cloud-Regionen, Edge-Standorte, Remote-Arbeitsplätze. Standortspezifische Risiken (Naturkatastrophen, politische Instabilität, Stromversorgung) müssen bewertet und im Inventar vermerkt werden.", descriptionEn: "We must document the geographic distribution of its assets — data centres, cloud regions, edge locations, remote workplaces. Location-specific risks (natural disasters, political instability, power supply) must be assessed and noted in the inventory.", reason: "Standortkonzentrationen schaffen regionale Ausfallrisiken, die ohne Dokumentation nicht sichtbar sind.", reasonEn: "Location concentrations create regional outage risks that are not visible without documentation.", whenRequired: "Erforderlich bei mehreren Standorten.", whenRequiredEn: "Required for multiple locations.", sources: ["ISO 27001:2022 A.7.5", "BSI-Standard 200-4", "NIST CSF 2.0 ID.RA"] },
  { id: "p08-c14", title: "Netzwerksegmentierungsanalyse", titleEn: "Network Segmentation Analysis", description: "Wir müssen die Netzwerksegmentierung im Kontext der Asset-Abhängigkeiten analysieren. Vertrauensgrenzen zwischen Segmenten müssen dokumentiert, Übergänge durch Firewalls und ACLs geschützt und unerlaubte Querverbindungen erkannt werden.", descriptionEn: "We must analyse network segmentation in the context of asset dependencies. Trust boundaries between segments must be documented, transitions protected by firewalls and ACLs, and unauthorised cross-connections detected.", reason: "Flache Netzwerke ermöglichen laterale Bewegung bei Kompromittierung eines einzelnen Assets.", reasonEn: "Flat networks enable lateral movement when a single asset is compromised.", whenRequired: "Erforderlich für alle Organisationen mit Netzwerk-Infrastruktur.", whenRequiredEn: "Required for all organisations with network infrastructure.", sources: ["ISO 27001:2022 A.8.22", "NIS2 Art.21(2)(b)", "BSI IT-Grundschutz NET.1.1"] },
  { id: "p08-c15", title: "Redundanz- und Failover-Dokumentation", titleEn: "Redundancy & Failover Documentation", description: "Für jedes kritische Asset müssen Redundanz- und Failover-Konfigurationen dokumentiert werden — aktive/passive Cluster, Load-Balancing, Geo-Redundanz, Backup-Systeme. Failover-Tests müssen regelmäßig durchgeführt und protokolliert werden.", descriptionEn: "For each critical asset, redundancy and failover configurations must be documented — active/passive clusters, load balancing, geo-redundancy, backup systems. Failover tests must be regularly performed and logged.", reason: "Undokumentierte Failover-Konfigurationen versagen im Ernstfall häufig aufgrund veränderter Umgebungsbedingungen.", reasonEn: "Undocumented failover configurations frequently fail in emergencies due to changed environmental conditions.", whenRequired: "Erforderlich für kritische Assets.", whenRequiredEn: "Required for critical assets.", sources: ["ISO 27001:2022 A.8.14", "BSI-Standard 200-4", "NIST CSF 2.0 PR.IR"] },
  { id: "p08-c16", title: "Disaster-Recovery-Abhängigkeiten", titleEn: "Disaster Recovery Dependencies", description: "Wir müssen die Abhängigkeiten für die Wiederherstellung nach einem Desaster dokumentieren — Wiederherstellungsreihenfolge basierend auf Abhängigkeitsketten, erforderliche Infrastruktur, Netzwerkvoraussetzungen und Personalressourcen. Die DR-Abhängigkeitsmatrix muss mit der BIA abgeglichen sein.", descriptionEn: "We must document dependencies for disaster recovery — recovery sequence based on dependency chains, required infrastructure, network prerequisites, and personnel resources. The DR dependency matrix must be aligned with the BIA.", reason: "Ohne Kenntnis der Wiederherstellungsabhängigkeiten scheitert DR an der falschen Reihenfolge.", reasonEn: "Without knowledge of recovery dependencies, DR fails due to incorrect sequencing.", whenRequired: "Erforderlich für alle Organisationen mit DR-Plan.", whenRequiredEn: "Required for all organisations with DR plan.", sources: ["ISO 22301:2019 §8.4", "BSI-Standard 200-4 Kap.7", "NIST CSF 2.0 RC.RP"] },
  { id: "p08-c17", title: "API- und Microservice-Inventar", titleEn: "API & Microservice Inventory", description: "Alle APIs und Microservices müssen inventarisiert werden — Endpunkt-URL, Authentifizierungsmethode, Datenklassifizierung, abhängige Konsumenten, SLA-Anforderungen und verantwortliches Team. API-Gateways müssen als zentrale Inventarquelle genutzt werden.", descriptionEn: "All APIs and microservices must be inventoried — endpoint URL, authentication method, data classification, dependent consumers, SLA requirements, and responsible team. API gateways must be used as central inventory source.", reason: "In Microservice-Architekturen sind APIs die primären Abhängigkeitspunkte — ohne Inventar entstehen blinde Flecken.", reasonEn: "In microservice architectures, APIs are the primary dependency points — without inventory, blind spots emerge.", whenRequired: "Erforderlich für API-basierte Architekturen.", whenRequiredEn: "Required for API-based architectures.", sources: ["ISO 27001:2022 A.8.20", "OWASP API Security", "NIST CSF 2.0 ID.AM"] },
  { id: "p08-c18", title: "Kryptographische Asset-Inventarisierung", titleEn: "Cryptographic Asset Inventory", description: "Wir müssen ein Inventar aller kryptographischen Assets führen — Zertifikate, Schlüssel, HSMs, Verschlüsselungsalgorithmen, TLS-Konfigurationen. Ablaufdaten müssen überwacht und rechtzeitig erneuert werden. Post-Quanten-Kryptografie-Readiness muss bewertet werden.", descriptionEn: "We must maintain an inventory of all cryptographic assets — certificates, keys, HSMs, encryption algorithms, TLS configurations. Expiry dates must be monitored and renewed timely. Post-quantum cryptography readiness must be assessed.", reason: "Abgelaufene Zertifikate und schwache Algorithmen sind häufige Ursachen für Ausfälle und Sicherheitsvorfälle.", reasonEn: "Expired certificates and weak algorithms are common causes of outages and security incidents.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.24", "BSI TR-02102", "NIS2 Art.21(2)(h)"] },
  { id: "p08-c19", title: "Shadow-IT-Erkennung und -Kontrolle", titleEn: "Shadow IT Detection & Control", description: "Wir müssen Prozesse und technische Maßnahmen implementieren, um nicht autorisierte IT-Systeme, Cloud-Dienste und Software (Shadow IT) zu erkennen. Erkannte Shadow-IT muss bewertet und entweder formalisiert (ins Inventar aufgenommen) oder abgeschaltet werden. Cloud Access Security Broker (CASB) und Network Monitoring müssen eingesetzt werden.", descriptionEn: "We must implement processes and technical measures to detect unauthorised IT systems, cloud services, and software (shadow IT). Detected shadow IT must be assessed and either formalised (added to inventory) or shut down. Cloud Access Security Broker (CASB) and network monitoring must be deployed.", reason: "Shadow IT entzieht sich allen Sicherheitskontrollen und schafft unkontrollierte Risiken.", reasonEn: "Shadow IT evades all security controls and creates uncontrolled risks.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.9", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 ID.AM-01"] },
  { id: "p08-c20", title: "Inventar-Audit und Qualitätssicherung", titleEn: "Inventory Audit & Quality Assurance", description: "Das Asset-Inventar und Abhängigkeitsregister müssen regelmäßig auf Vollständigkeit, Aktualität und Korrektheit geprüft werden — Stichproben-Audits, Abgleich mit Netzwerk-Scans, Validierung durch Asset-Eigentümer. Abweichungen müssen als Findings dokumentiert und behoben werden.", descriptionEn: "The asset inventory and dependency register must be regularly checked for completeness, currency, and correctness — sample audits, reconciliation with network scans, validation by asset owners. Deviations must be documented as findings and remediated.", reason: "Ohne Qualitätssicherung degradiert die Inventarqualität kontinuierlich und wird für Entscheidungen unbrauchbar.", reasonEn: "Without quality assurance, inventory quality continuously degrades and becomes unusable for decisions.", whenRequired: "Mindestens halbjährlich.", whenRequiredEn: "At least semi-annually.", sources: ["ISO 27001:2022 §9.2", "BSI IT-Grundschutz ORP.1", "NIST CSF 2.0 ID.AM"] },
  { id: "p08-c21", title: "Vertrauensgrenzen und Zonenmodell", titleEn: "Trust Boundaries & Zone Model", description: "Wir müssen ein Zonenmodell definieren, das Vertrauensgrenzen zwischen verschiedenen Netzwerk- und Anwendungsbereichen abbildet — DMZ, interne Zonen, Management-Netz, OT-Zone, Cloud-Zone. Assets müssen ihrer Zone zugeordnet und Übergänge zwischen Zonen durch definierte Kontrollpunkte geschützt werden.", descriptionEn: "We must define a zone model mapping trust boundaries between different network and application areas — DMZ, internal zones, management network, OT zone, cloud zone. Assets must be assigned to their zone and transitions between zones protected by defined control points.", reason: "Ohne klares Zonenmodell fehlt die Grundlage für eine wirksame Netzwerksegmentierung und Zugriffskontrolle.", reasonEn: "Without a clear zone model, the foundation for effective network segmentation and access control is missing.", whenRequired: "Erforderlich für alle Organisationen mit Netzwerk-Infrastruktur.", whenRequiredEn: "Required for all organisations with network infrastructure.", sources: ["ISO 27001:2022 A.8.22", "BSI IT-Grundschutz NET.1.1", "NIST CSF 2.0 PR.IR"] },
  { id: "p08-c22", title: "OT/ICS-spezifische Inventarisierung", titleEn: "OT/ICS-Specific Inventory", description: "Operative Technologie und industrielle Steuerungssysteme müssen mit OT-spezifischen Attributen separat inventarisiert werden — SCADA-Systeme, SPS/PLC, Sensoren, Aktoren, Firmware-Versionen, Kommunikationsprotokolle (Modbus, OPC UA), physische Standorte und Wartungszyklen.", descriptionEn: "Operational technology and industrial control systems must be separately inventoried with OT-specific attributes — SCADA systems, PLCs, sensors, actuators, firmware versions, communication protocols (Modbus, OPC UA), physical locations, and maintenance cycles.", reason: "OT-Assets haben andere Attribute, Protokolle und Lebenszyklen als IT — ein IT-zentriertes Inventar erfasst sie unzureichend.", reasonEn: "OT assets have different attributes, protocols, and lifecycles than IT — an IT-centric inventory captures them inadequately.", whenRequired: "Erforderlich für Organisationen mit OT/ICS-Systemen.", whenRequiredEn: "Required for organisations with OT/ICS systems.", sources: ["IEC 62443", "NIS2 Art.21(2)(a)", "BSI ICS-Security Kompendium"] },
  { id: "p08-c23", title: "Überprüfung der Inventar- und Abhängigkeits-Richtlinie", titleEn: "Review of Inventory & Dependency Policy", description: "Diese Richtlinie muss mindestens jährlich überprüft werden. Erkenntnisse aus Inventar-Audits, Vorfällen (insbesondere kaskadierenden Ausfällen) und Änderungen der IT-Landschaft müssen in die Überprüfung einfließen. Neue Asset-Typen (z.B. IoT, KI-Modelle) müssen bei Bedarf in das Datenmodell aufgenommen werden.", descriptionEn: "This policy must be reviewed at least annually. Insights from inventory audits, incidents (especially cascading failures), and changes to the IT landscape must feed into the review. New asset types (e.g., IoT, AI models) must be incorporated into the data model as needed.", reason: "Die IT-Landschaft verändert sich dynamisch — die Inventar-Richtlinie muss Schritt halten.", reasonEn: "The IT landscape changes dynamically — the inventory policy must keep pace.", whenRequired: "Mindestens jährlich.", whenRequiredEn: "At least annually.", sources: ["ISO 27001:2022 A.5.1", "BSI-Standard 200-1", "NIST CSF 2.0 GV.PO"] },
];

// Re-export for aggregator
export const clauseExport: Record<string, PolicyClause[]> = { p07, p08 };
